def hidden_rule_fn(state):
    def toroidal_delta(a, b):
        d = (b - a) % 8
        if d > 4:
            d -= 8
        return d

    def chromodist(p, q):
        dx = toroidal_delta(p['x'], q['x'])
        dy = toroidal_delta(p['y'], q['y'])
        return max(abs(dx), abs(dy)) + (0 if p['type'] == q['type'] else 1)

    def find_target(p, others):
        zexes = [q for q in others if q['type'] == 'ZEX']
        if not zexes:
            return p
        best = None
        best_dist = float('inf')
        for q in zexes:
            d = chromodist(p, q)
            if d < best_dist or (d == best_dist and (q['x'], q['y']) < (best['x'], best['y'])):
                best_dist = d
                best = q
        return best

    result = []
    for i, p in enumerate(state):
        others = [state[j] for j in range(len(state)) if j != i]
        target = find_target(p, others)

        if p['type'] == 'ZEX':
            # If exactly adjacent (chromodist == 1), swap positions
            if chromodist(p, target) == 1:
                result.append({'type': 'ZEX', 'x': target['x'], 'y': target['y']})
            else:
                dx = toroidal_delta(p['x'], target['x'])
                dy = toroidal_delta(p['y'], target['y'])
                sx = 1 if dx > 0 else (-1 if dx < 0 else 0)
                sy = 1 if dy > 0 else (-1 if dy < 0 else 0)
                result.append({'type': 'ZEX', 'x': (p['x'] + sx) % 8, 'y': (p['y'] + sy) % 8})
        else: # GLORP
            dx = toroidal_delta(p['x'], target['x'])
            dy = toroidal_delta(p['y'], target['y'])
            # Prefer x-axis on tie
            if abs(dx) >= abs(dy):
                d = dx
                axis = 'x'
            else:
                d = dy
                axis = 'y'
            # Move away: opposite sign of delta
            step = -1 if d > 0 else (1 if d < 0 else 0)
            nx, ny = p['x'], p['y']
            if axis == 'x':
                nx = (nx + step) % 8
            else:
                ny = (ny + step) % 8
            result.append({'type': 'GLORP', 'x': nx, 'y': ny})
    return result
